INSERT INTO services (slug, locale, status, sort_order, title, h1, overview, scope_items, gallery, seo, tiers, event_checklist, extended_bullets, related_work, tertiary_cta, hub, published_at, created_at, updated_at) VALUES ('branding-visual-identity', 'en', 'published', 0, 'Branding', 'BRANDING', 'From logo design to visual identity development and uplifting, our team of branding experts is dedicated to helping you establish a credible and trustworthy brand that drives long-term success for your business.', '["Logo design","Visual identity systems","Brand colors & typography","Company profiles","Brand guidelines","Stationery"]', '[{"alt":"Brand identity showcase","src":"/images/services/branding/gallery-01.jpg","width":1600,"height":1200},{"alt":"Business card design","src":"/images/services/branding/gallery-02.jpg","width":1600,"height":1200},{"alt":"Letterhead stationery","src":"/images/services/branding/gallery-03.jpg","width":1600,"height":1200},{"alt":"Brand guidelines document","src":"/images/services/branding/gallery-04.jpg","width":1600,"height":1200},{"alt":"Logo applications","src":"/images/services/branding/gallery-05.jpg","width":1600,"height":1200},{"alt":"Visual identity system","src":"/images/services/branding/gallery-06.jpg","width":1600,"height":1200}]', '{"title":"Branding | Propagenda","description":"Strategy-first branding, logo, identity systems, stationery tiers, and brand guidelines."}', '[{"name":"Basic branding","items":["Logo, color palette, font, pattern","Bonus: basic stationery (business card, letterhead, envelopes)"]},{"name":"Developed branding","items":["All basic guidelines plus marketing materials, brand voice, messaging, and values"]}]', NULL, NULL, '[{"href":"/work/sanapex-interiors","label":"Sanapex Interiors"},{"href":"/work/p2p-motors","label":"P2P Motors"}]', NULL, '{"tag":"brand","image":"/images/services/branding-and-visual-identity.jpg","preview":"/images/portfolio/work-sanapex.webp","descriptor":"Logos, identity systems & guidelines"}', '2026-09-14T22:47:51.118+00:00', '2026-09-02T17:11:58.944668+00:00', '2026-09-14T22:47:51.546142+00:00');
