INSERT INTO services (slug, locale, status, sort_order, title, h1, overview, scope_items, gallery, seo, tiers, event_checklist, extended_bullets, related_work, tertiary_cta, hub, published_at, created_at, updated_at) VALUES ('mobile-applications', 'en', 'published', 4, 'Mobile Applications', 'MOBILE APPLICATIONS', 'From first sketch to store launch: apps that strengthen your brand and delight users.', '["iOS & Android apps","Cross-platform development","Mobile UX/UI design","API & backend integration","App Store & Play Store launch","Maintenance & updates"]', '[]', '{"title":"Mobile Applications | Propagenda","description":"User-friendly mobile apps that enhance your brand and delight users."}', NULL, NULL, NULL, NULL, NULL, '{"tag":"digital","image":"/images/services/mobile-apps.jpg","preview":"/images/portfolio/work-sanapex.webp","descriptor":"Apps that delight users"}', '2026-09-14T22:47:51.118+00:00', '2026-09-02T17:11:58.944668+00:00', '2026-09-14T22:47:51.546142+00:00');
