INSERT INTO services (slug, locale, status, sort_order, title, h1, overview, scope_items, gallery, seo, tiers, event_checklist, extended_bullets, related_work, tertiary_cta, hub, published_at, created_at, updated_at) VALUES ('photography-videography', 'en', 'published', 6, 'Photography & Videography', 'PHOTOGRAPHY & VIDEOGRAPHY', 'Design-led visual content, led by photography: product, brand, lifestyle, editorial, food, real estate, portraits, events, and drone. Every frame art-directed to match your identity. Video is a supporting layer for when motion tells the story better: short brand films, product and testimonial clips, and motion graphics.', '["Product & brand photography","Lifestyle & editorial","Real estate & interiors","Event coverage","Supporting brand video","Motion graphics"]', '[{"alt":"Product photography","src":"/images/services/photography/gallery-01.jpg","width":1600,"height":1200},{"alt":"Lifestyle editorial shoot","src":"/images/services/photography/gallery-02.jpg","width":1600,"height":1200},{"alt":"Event coverage","src":"/images/services/photography/gallery-03.jpg","width":1600,"height":1200},{"alt":"Real estate photography","src":"/images/services/photography/gallery-04.jpg","width":1600,"height":1200},{"alt":"Brand video production","src":"/images/services/photography/gallery-05.jpg","width":1600,"height":1200},{"alt":"Motion graphics reel","src":"/images/services/photography/gallery-06.jpg","width":1600,"height":1200}]', '{"title":"Photography & Videography | Propagenda","description":"Brand, product, lifestyle, and real-estate photography that makes your identity look as considered as it is, with supporting video when a story needs motion."}', NULL, NULL, NULL, '[{"href":"/work/clemson-porter-properties","label":"Clemson Porter Properties"}]', '{"href":"/contact","label":"Book your shoot today"}', '{"tag":"production","image":"/images/services/photography-vid.jpg","preview":"/images/portfolio/work-food.webp","descriptor":"Your brand story, captured"}', '2026-09-14T22:47:51.118+00:00', '2026-09-02T17:11:58.944668+00:00', '2026-09-14T22:47:51.546142+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('sanapex-interiors', 'en', 'published', 0, 'Sanapex Interiors: Full Branding & Digital Presence', 'SANAPEX INTERIORS: FULL BRANDING & DIGITAL PRESENCE', 'featured', 'Property & interiors', 'A high-end interiors studio. We gave it an identity as refined as the spaces it designs.', '["Logo design and complete bilingual (English/Arabic) brand identity, built on a mark combining the Latin \"N\" with the Arabic nūn (نَ)","Full brand guidelines document: brand story, values, target audience, logo construction, clear-space and misuse rules, colors, typography, pattern, icons, social media and application templates","Brand colors: black, white, beige and warm-grey tones","Typography system: Viola for headings, Poppins for body text","Company profile and portfolio design","Website design and structure","Print and digital brand assets"]', '[{"alt":"Sanapex Interiors brand identity system, stationery, catalogue and collateral in a warm sand palette.","src":"/images/work/sanapex-interiors/hero.webp","width":1241,"height":1754},{"alt":"Sanapex Interiors social campaign featuring editorial interior design projects.","src":"/images/work/sanapex-interiors/gallery-1.webp","width":1241,"height":1754},{"alt":"Sanapex Interiors logo variations: horizontal and vertical lockups of the bilingual \"N\" and Arabic nūn mark, paired with the SANAPEX INTERIORS wordmark.","src":"/images/work/sanapex-interiors/gallery-2.webp","width":1920,"height":1080},{"alt":"Sanapex Interiors typography system: Viola for headings and Poppins for body text.","src":"/images/work/sanapex-interiors/gallery-3.webp","width":1920,"height":1080},{"alt":"Sanapex Interiors repeating pattern built from the interlocking \"N\" and Arabic nūn logo mark.","src":"/images/work/sanapex-interiors/gallery-4.webp","width":1920,"height":1080}]', '{"title":"Sanapex Interiors: Full Branding & Digital Presence | Propagenda","description":"Full visual identity and digital presence for a high-end interior design studio in Dubai."}', 'Sanapex Interiors', 'Interior Design', '2024', '/images/work/sanapex-interiors/hero.webp', '["Logo and complete brand identity: horizontal (primary), vertical and logo-mark-only lockups","Full brand guidelines document with logo construction, clear-space and misuse rules","Brand colors: black, white, beige (#BAA58D) and warm grey (#CEC5B6), with hex values","Typography system: Viola headings paired with Poppins body text","A repeating pattern built from the interlocking logo mark","Icon set for contact points: Instagram, Facebook, phone, email and location, in solid-black and beige treatments","Stationery and print collateral: business cards, envelopes, catalogue, quotation and invoice templates","Social media templates and branded merchandise","Company profile and portfolio design","Website design and structure"]', NULL, 'World-class craft. A brand that still looked improvised.', 'Logo to website: one refined system, built to signal premium from the first glance.', 'Every touchpoint now reads as high-end before the first meeting.', NULL, NULL, 'bnk-group', 'p2p-motors', '2026-09-14T22:47:51.118+00:00', '2026-09-02T17:11:59.109383+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('p2p-motors', 'en', 'published', 1, 'P2P Motors: Full Branding & Visual Identity', 'P2P MOTORS: FULL BRANDING & VISUAL IDENTITY', 'featured', 'Automotive', 'Luxury vehicle export, Dubai. We built a bold identity that travels as far as the cars do.', '["Logo design built on a hidden-meaning monogram: mirrored \"P\"s forming a car-front silhouette, with the negative space between them reading as a \"2\" (for \"P2P\") and the extended arrow strokes doubling as a streamlined bumper and export/forward-motion cue","Brand colors: black and a gold gradient (#594017 to #fdcb6b) as the primary pairing, with dark grey and white as a secondary palette","Typography system: Good Times Rg for headings, Helvetica Neue for body text","Two supporting repeating patterns built from the logo''s arrow motif","Custom icon style for Facebook, Messenger, Instagram, WhatsApp, TikTok and YouTube","Company profile/brochure design","Production of physical assets: dealer and feather flags, an outdoor billboard, showroom wall art and a branded vehicle-wrap pattern","Social media style guide and Instagram highlight/story templates","Print materials and internal tools: stationery, invoice and quotation templates, a bilingual (English/Arabic) company rubber stamp for P2P LLC, and staff ID/lanyard"]', '[{"alt":"P2P Motors luxury vehicle-export brand identity, gold-on-black stationery, dealer flags, signage and showroom collateral.","src":"/images/work/p2p-motors/hero.webp","width":1241,"height":1754},{"alt":"P2P Motors showroom and worldwide-shipping social campaign with premium blacked-out vehicles.","src":"/images/work/p2p-motors/gallery-1.webp","width":1241,"height":1754},{"alt":"P2P Motors brand colors: black and a gold gradient (#594017 to #fdcb6b) shown on a gold-liveried sports car.","src":"/images/work/p2p-motors/gallery-2.webp","width":1920,"height":1080},{"alt":"P2P Motors logo construction: mirrored \"P\"s forming a car-front silhouette, a hidden \"2\" in the negative space, and arrow strokes forming a streamlined bumper.","src":"/images/work/p2p-motors/gallery-3.webp","width":1920,"height":1080},{"alt":"P2P Motors typography system: Good Times Rg for headings and Helvetica Neue for body text.","src":"/images/work/p2p-motors/gallery-4.webp","width":1920,"height":1080}]', '{"title":"P2P Motors: Full Branding & Visual Identity | Propagenda","description":"Case study: bold branding for a Dubai luxury and specialty vehicle export company."}', 'P2P Motors', 'Automotive Export', '2024', '/images/work/p2p-motors/hero.webp', '["Logo and complete brand identity, with a documented logo-construction rationale","Brand colors (black and gold gradient, plus a dark-grey-and-white secondary palette), typography and pattern system","Company profile design","Physical assets: dealer and feather flags, showroom wall art, branded vehicle wrap, car cover and sunshade","Social media style guide, icon set and Instagram story/highlight templates","Print materials and internal tools: stationery, presentation folder, invoice/quotation templates, bilingual (English/Arabic) company stamp for P2P LLC, staff lanyard and ID","Corporate merchandise: branded mug, keychain, t-shirt and cap"]', NULL, 'Global scale. Branding that still felt local and soft.', 'Full branding: profile, socials, flags, showroom. One confident system.', 'Digital to physical, every surface now says premium and international.', NULL, NULL, 'sanapex-interiors', 'dose-pharmacy', '2026-09-14T22:47:51.118+00:00', '2026-09-02T17:11:59.109383+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('dose-pharmacy', 'en', 'published', 2, 'Dose Pharmacy: Branding & Identity', 'DOSE PHARMACY: BRANDING & IDENTITY', 'featured', 'Healthcare & retail', 'A Saudi pharmacy brand built to reassure in two languages. One coral leaf-and-wing mark, carried from the business card to the billboard.', '["Logo design and complete bilingual (English/Arabic) brand identity: a coral leaf-and-wing \"D + P\" monogram with English and Arabic wordmarks","Bilingual brand tagline: \"Your Daily Dose of Wellness\" / \"جرعتك اليومية من العافية\"","Brand colors and typography system","Stationery: business cards, envelopes, letterhead and a presentation folder","Spiral-bound, tab-divided branded notebook","Staff identity: ID badge, lanyard and lab-coat branding","Desk name plate","Packaging color concepts for pill bottles","Outdoor advertising: an Arabic-language billboard concept"]', '[{"alt":"Dose Pharmacy brand kit cover: the coral leaf-and-wing \"D + P\" mark above the DOSE PHARMACY wordmark.","src":"/images/work/dose-pharmacy/hero.webp","width":1847,"height":1038},{"alt":"Dose Pharmacy outdoor billboard concept in coral and black, with an Arabic headline and a masked pharmacist holding medication.","src":"/images/work/dose-pharmacy/gallery-1.webp","width":1920,"height":1080},{"alt":"Dose Pharmacy business card mockup in cream and coral, with the leaf-and-wing \"D + P\" mark on the front and the Arabic wordmark on the reverse.","src":"/images/work/dose-pharmacy/gallery-2.webp","width":1920,"height":1080},{"alt":"Dose Pharmacy envelope and card mockup with the \"Your Daily Dose of Wellness\" tagline and a repeating leaf-and-wing pattern.","src":"/images/work/dose-pharmacy/gallery-3.webp","width":1920,"height":1080},{"alt":"Dose Pharmacy spiral-bound notebook mockup with coral tabbed dividers and the Arabic tagline \"جرعتك اليومية من العافية\" (Your Daily Dose of Wellness).","src":"/images/work/dose-pharmacy/gallery-4.webp","width":1920,"height":1080},{"alt":"Dose Pharmacy pill-bottle packaging concept in charcoal and coral, each stamped with the leaf-and-wing \"D + P\" mark.","src":"/images/work/dose-pharmacy/gallery-5.webp","width":1920,"height":1080}]', '{"title":"Dose Pharmacy: Branding & Identity | Propagenda","description":"Case study: bilingual (English/Arabic) brand identity for a Saudi pharmacy brand."}', 'Dose Pharmacy', 'Retail Pharmacy', '2023', '/images/work/dose-pharmacy/hero.webp', '["Logo and complete bilingual brand identity: coral leaf-and-wing \"D + P\" monogram with English and Arabic wordmarks","Bilingual tagline: \"Your Daily Dose of Wellness\"","Brand colors and typography system","Stationery: business cards, envelopes, letterhead and presentation folder","Branded notebook with tabbed dividers","Staff badge, lanyard and lab-coat branding","Desk name plate, pill-bottle packaging colorways and a billboard concept"]', NULL, 'Clinical trust and everyday warmth, in two languages. Most pharmacy brands manage one.', 'A coral leaf-and-wing "D + P" mark built to run bilingual, carried through stationery, staff badges and lab coats, a tabbed notebook, packaging colorways and an Arabic billboard concept.', 'One bilingual identity system, from business card to billboard, built around the line "Your Daily Dose of Wellness."', NULL, NULL, 'p2p-motors', 'clemson-porter-properties', '2026-09-14T22:47:51.118+00:00', '2026-09-02T17:11:59.109383+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('clemson-porter-properties', 'en', 'published', 3, 'Clemson Porter Properties: Full Rebranding', 'CLEMSON PORTER PROPERTIES: FULL REBRANDING', 'featured', 'Property & interiors', 'UAE property brokerage. A quiet-luxury rebrand for clients who notice everything.', '["Full visual identity guidelines: brand essence, values and personality","Geometric logo system built from interlocking \"C\" and \"P\" marks, with primary, vertical, simplified and submark lockups","Bilingual (English/Arabic) typography system","A \"quiet luxury\" color palette and a vertical/horizontal pattern built from the logo shapes","Stationery: business cards, letterhead and envelopes","Presentation folder, spiral-bound notebook and desk name plate","Staff lapel pin, ID badge and lanyard","Feather flags, branded mugs and outdoor signage guidance"]', '[{"alt":"Clemson Porter Properties business card mockup in dark olive with the geometric C+P mark, front and back.","src":"/images/work/clemson-porter-properties/hero.webp","width":1920,"height":1080},{"alt":"Clemson Porter Properties rooftop billboard reading \"Invest smart. Live fine.\" beside the logo lockup.","src":"/images/work/clemson-porter-properties/gallery-1.webp","width":1920,"height":1080},{"alt":"Clemson Porter Properties presentation folder and property-document sheet with the logo and \"Clarity. Control. Confidence.\" tagline.","src":"/images/work/clemson-porter-properties/gallery-2.webp","width":1920,"height":1080},{"alt":"Clemson Porter Properties brand color story: black, dark olive, walnut brown and bone with the geometric pattern.","src":"/images/work/clemson-porter-properties/gallery-3.webp","width":1080,"height":1350}]', '{"title":"Clemson Porter Properties: Full Rebranding | Propagenda","description":"Case study: quiet-luxury rebranding for a UAE property brokerage."}', 'Clemson Porter Properties Brokers', 'Real Estate Brokerage', '2025', '/images/work/clemson-porter-properties/hero.webp', '["Full visual identity guidelines document","Logo system: primary, vertical, simplified and submark lockups","Bilingual (English/Arabic) typography system","Color palette and geometric pattern system","Stationery: business cards, letterhead, envelopes and presentation folder","Notebook, desk name plate, lapel pin, ID badge and lanyard","Feather flags, mugs and outdoor signage application"]', NULL, 'A premium property brokerage with no consistent visual identity to match its client base.', 'A geometric mark fusing "C" and "P" into a building-like form, carried through a quiet-luxury palette of black, dark olive, walnut brown and bone across every touchpoint.', 'One documented system, from business card to billboard, under the line "Clarity. Control. Confidence."', NULL, NULL, 'dose-pharmacy', 'sealand', '2026-09-14T22:47:51.118+00:00', '2026-09-02T17:11:59.109383+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('sealand', 'en', 'published', 4, 'Sealand: Rebranding & Visual Identity', 'SEALAND: REBRANDING & VISUAL IDENTITY', 'featured', 'Food & hospitality', 'A Dubai seafood restaurant since 1982. We modernized its identity without spending down four decades of trust.', '["Logo redesign and complete bilingual (English/Arabic) brand identity system","Brand colors, typography, and visual language","Packaging design: paper bags, takeaway bowls and containers","Staff uniform design: chef jackets, aprons, captain and waiter jackets, housekeeping wear","Front-of-house collateral: menus, guest checks, reserved-table signage, stationery","Social media style guide and templates"]', '[{"alt":"Sealand seafood restaurant brand identity: navy waist apron with a gold-embroidered crest and a wave-pattern pocket.","src":"/images/work/sealand/hero.webp","width":1200,"height":1800},{"alt":"Sealand captain and waiter jackets with a gold-embroidered crest, part of the bilingual restaurant identity.","src":"/images/work/sealand/gallery-1.webp","width":1600,"height":900},{"alt":"Sealand branded paper bags in navy and cream, with the Arabic wordmark, gold crest and orange-and-navy wave motif.","src":"/images/work/sealand/gallery-2.webp","width":1600,"height":900},{"alt":"Sealand brand guideline color palette: Navy Blue, Indigo Dye, Tangerine, Earth Yellow and Alabaster swatches with CMYK values.","src":"/images/work/sealand/gallery-3.webp","width":960,"height":540}]', '{"title":"Sealand: Rebranding & Visual Identity | Propagenda","description":"Case study: rebranding and a full bilingual visual identity system for a Dubai seafood restaurant serving since 1982."}', 'Sealand', 'Seafood Restaurant', '2025', '/images/work/sealand/hero.webp', '["Full logo system: primary, horizontal, Arabic horizontal/vertical, combined and simplified marks","Bilingual (English/Arabic) brand identity system","Color palette, typography and icon set","Packaging: paper bags and takeaway bowls","Staff uniforms: chef jackets, aprons, captain/waiter jackets and housekeeping wear","Stationery and print collateral: business cards, letterhead, envelopes, presentation folder","Menu and guest-check design, reserved-table signage","Social media style guide"]', NULL, 'Four decades of trust in Dubai. A visual identity that needed to feel current without losing what made it familiar.', 'A bilingual system built on a navy-and-tangerine palette and a recurring sea-and-land wave motif, carried through packaging, uniforms and every guest-facing touchpoint.', 'One consistent system now carries the Sealand name from the kitchen to the paper bag guests take home.', NULL, NULL, 'clemson-porter-properties', 'bnk-group', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('bnk-group', 'en', 'published', 5, 'The BNK Group: Branding & Visual Identity', 'THE BNK GROUP: BRANDING & VISUAL IDENTITY', 'featured', 'Property & interiors', 'A luxury design-build studio entering the UAE. We gave it one bilingual identity, from the logo to the letterhead.', '["Logo design and complete brand identity: vertical, horizontal and mark-only lockups","Bilingual (English/Arabic) typography and brand voice","Brand colors and a supporting geometric pattern system","Stationery: business cards, letterhead and envelopes","Presentation folder and project-document templates","Staff ID badge and lanyard design","Social media application templates and video-thumbnail style"]', '[{"alt":"The BNK Group business card mockup in navy with a red interlocking-K mark, on marble.","src":"/images/work/bnk-group/hero.webp","width":1920,"height":1080},{"alt":"The BNK Group staff ID badge and lanyard in a navy-and-white geometric pattern.","src":"/images/work/bnk-group/gallery-1.webp","width":764,"height":1080},{"alt":"The BNK Group letterhead stationery mockup with the logo lockup and bilingual footer details.","src":"/images/work/bnk-group/gallery-2.webp","width":1920,"height":1080},{"alt":"The BNK Group social media before-and-after interior design carousel, in English and Arabic.","src":"/images/work/bnk-group/gallery-3.webp","width":1920,"height":1080}]', '{"title":"The BNK Group: Branding & Visual Identity | Propagenda","description":"Case study: full bilingual (English/Arabic) brand identity and stationery system for a UAE luxury interior design-build studio."}', 'The BNK Group', 'Interior Design & Build', NULL, '/images/work/bnk-group/hero.webp', '["Logo and complete brand identity system","Bilingual (English/Arabic) typography and brand voice","Brand colors and pattern system","Stationery: business cards, letterhead and envelopes","Presentation folder and project-document templates","Staff ID badge and lanyard","Social media templates and video-thumbnail style"]', NULL, 'A boutique design-build studio expanding into the UAE. No consistent identity to match the ambition.', 'One bilingual system: mark, stationery, ID and social templates, built to travel from site visit to Instagram.', 'Every touchpoint, in English or Arabic, now reads as one confident, camera-ready brand.', NULL, NULL, 'sealand', 'sanapex-interiors', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('emirates-agro', 'en', 'published', 6, 'Emirates Agro: Rebranding & Visual Identity', 'EMIRATES AGRO: REBRANDING & VISUAL IDENTITY', 'more', 'Industry & energy', 'Since 1981. We rebranded a global agro supplier for the next forty years.', '["Logo redesign and full brand identity","Visual direction rooted in agriculture and sustainability","Company profile design","Refined color palette: layered greens, almond, and dun tones","Minimal, clean layout system with a focus on clarity and trust"]', '[]', '{"title":"Emirates Agro: Rebranding & Visual Identity | Propagenda","description":"Case study: heritage-forward rebranding for a global agricultural supplier."}', 'Emirates Agro', 'Agriculture & Petrochemicals', '2023', NULL, '["Logo redesign and full brand identity","Agriculture and sustainability-led visual direction","Company profile design","Refined palette: layered greens, almond, and dun tones","Minimal, clean layout system"]', '[{"label":"Heritage","value":"Since 1981"},{"label":"Product lines unified","value":"3"},{"label":"Profile and collateral","value":"Full suite"}]', 'Deep heritage. A brand that no longer looked global.', 'Greens, clarity, trust: identity rooted in land and scale.', 'Four decades of legacy, one modern visual language.', '{"text":"Four decades of history, finally captured in a brand that looks ahead.","author":"Brand Lead, Emirates Agro"}', NULL, 'mm-event-management', 'zealerz', '2026-09-14T22:47:51.118+00:00', '2026-09-02T17:11:59.109383+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('zealerz', 'en', 'published', 7, 'Zealerz: Branding & Visual Identity', 'ZEALERZ: BRANDING & VISUAL IDENTITY', 'more', 'Industry & energy', 'A Dubai virtual marketplace built to fix a fragmented LPG supply chain. One mark, one app, one brand system across B2B and B2C.', '["Logo design built on a mirrored double-\"Z\" monogram, in green and navy","Brand colors: green (#76AA42) and navy (#000045), with documented CMYK values and tint scales","Typography system: Montserrat for headings","A repeating pattern built from the double-\"Z\" monogram, in light and dark treatments","Custom icon set for the marketplace categories (fuel, LPG cylinders, solar panels, EV charging, oil) alongside social icons (TikTok, Instagram, LinkedIn, Facebook)","Social media style guide: Instagram-grid templates covering delivery, propane-vs-butane education and app promotion","App UI for the iOS/Android marketplace, spanning home, offers, categories and a mall-partner marketplace card","Physical brand rollout: stationery, presentation folder, staff ID/lanyard, branded truck and delivery-scooter livery, a mobile billboard trailer, and merchandise (mug, cap, polo, phone case)"]', '[{"alt":"Zealerz LPG delivery app and brand identity, delivery trucks, gas cylinders and solar in a green industrial palette.","src":"/images/work/zealerz/hero.webp","width":1241,"height":1754},{"alt":"Zealerz brand colors: green (#76AA42) and navy (#000045) shown across the double-\"Z\" logo mark, with CMYK values and tint percentages.","src":"/images/work/zealerz/gallery-1.webp","width":1920,"height":1080},{"alt":"Zealerz typography system: Montserrat used for headings on a navy background.","src":"/images/work/zealerz/gallery-2.webp","width":1920,"height":1080},{"alt":"Zealerz social media style guide: Instagram post templates covering propane-vs-butane education, the delivery app, LPG cylinders and UAE-wide delivery.","src":"/images/work/zealerz/gallery-3.webp","width":1920,"height":1080},{"alt":"Zealerz branded delivery truck livery in green and navy, reading \"Transforming LPG delivery with technology.\"","src":"/images/work/zealerz/gallery-4.webp","width":1920,"height":1080}]', '{"title":"Zealerz: Branding & Visual Identity | Propagenda","description":"Case study: brand identity and app design for an LPG marketplace."}', 'Zealerz', 'LPG Marketplace & Logistics', '2024', '/images/work/zealerz/hero.webp', '["Logo and complete brand identity, with documented construction and clear-space rules","Brand colors (#76AA42 green, #000045 navy) and Montserrat typography system","Repeating pattern and custom icon set for marketplace categories and social channels","Stationery: business cards, letterhead, envelopes and a presentation folder","Staff ID badge and lanyard","Social media style guide and a set of Instagram post templates","App UI: onboarding, home feed, category browse and a partner-marketplace card (e.g. a Cityland Mall offer)","Vehicle livery: branded delivery truck, delivery scooter and a mobile roadside billboard trailer promoting the app","Merchandise: mug, cap, polo shirt and phone case"]', NULL, 'A fragmented, low-trust LPG supply chain. A brand and app that had to make ordering gas feel simple.', 'A double-"Z" monogram in green and navy, carried from the app UI through vehicle livery, stationery and social templates, built to connect suppliers and customers on one platform.', 'One brand system spanning app, fleet and physical collateral, built to serve both B2B and B2C LPG ordering across the UAE.', NULL, NULL, 'emirates-agro', 'arabian-business-academy', '2026-09-14T22:47:51.118+00:00', '2026-09-02T17:11:59.109383+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('arabian-business-academy', 'en', 'published', 8, 'Arabian Business Academy: Roll-Up Banner Campaign', 'ARABIAN BUSINESS ACADEMY: ROLL-UP BANNER CAMPAIGN', 'more', 'Finance', 'A Dubai trading academy with offices across three countries. We gave its exhibition stands one consistent bilingual voice.', '["Bilingual (Arabic/English) roll-up banner design across five distinct messages","Consistent application of the existing navy-and-gold crest and color system","Layout for platform sign-up, expert-led courses, an investment fund, and an economic-news portal","Contact and social details for the UAE, Iraq and Turkey offices on every banner"]', '[{"alt":"Arabian Business Academy roll-up banner with the navy-and-gold shield crest and bilingual Arabic/English headline over a stock-chart background.","src":"/images/work/arabian-business-academy/hero.webp","width":1911,"height":1911},{"alt":"Arabian Business Academy roll-up banner promoting round-the-clock trading access and a $35 deposit bonus, with UAE, Iraq and Turkey office details.","src":"/images/work/arabian-business-academy/gallery-1.webp","width":1911,"height":1911},{"alt":"Arabian Business Academy roll-up banner for its \"Rotterdam Fund,\" listing projected annual and monthly returns and a minimum deposit.","src":"/images/work/arabian-business-academy/gallery-2.webp","width":1911,"height":1911},{"alt":"Arabian Business Academy roll-up banner promoting its Arabic economic-news and technical-analysis website, abacademyco.com.","src":"/images/work/arabian-business-academy/gallery-3.webp","width":1911,"height":1911},{"alt":"Arabian Business Academy roll-up banner featuring a financial analyst alongside the navy-and-gold shield crest.","src":"/images/work/arabian-business-academy/gallery-4.webp","width":1911,"height":1911}]', '{"title":"Arabian Business Academy: Roll-Up Banner Campaign | Propagenda","description":"Case study: a bilingual roll-up banner campaign for a Dubai-based trading education and financial-markets brand."}', 'Arabian Business Academy (ABA)', 'Financial Trading Education', NULL, '/images/work/arabian-business-academy/hero.webp', '["Five roll-up/pull-up banner designs, print-ready","Consistent bilingual layout system across offers and audiences","Office and social-contact footer applied across the set"]', NULL, 'Five different messages, three offices, two languages. One stand had to carry all of it without looking improvised.', 'One recurring layout, the existing navy-and-gold crest, and a shared footer, applied consistently across trading, courses, the fund and the news portal.', 'A consistent exhibition presence across sign-up, education, fund and media messaging, in Arabic and English.', NULL, NULL, 'zealerz', '2k-shopping', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('2k-shopping', 'en', 'published', 9, '2K Shopping: Branding & Visual Identity', '2K SHOPPING: BRANDING & VISUAL IDENTITY', 'more', 'Healthcare & retail', 'A UAE online grocery platform. We gave it one bold identity, from the app splash screen to the delivery van.', '["Brand strategy: positioning, target audience, value proposition, core values and tone of voice","Logo design and complete brand identity: construction, concept, and vertical/horizontal/simplified-mark variations","Bilingual (English/Arabic) typography system, color palette and icon style","Packaging and delivery collateral: shipping boxes, delivery bags/backpacks and branded tape","Fleet livery, billboard and staff uniform design","Stationery and office collateral: business cards, letterhead, presentation folder, staff ID badge and notebook"]', '[{"alt":"2K Shopping delivery van livery in teal, with the bilingual (English/Arabic) shopping-cart-and-K logo, app-store badges and a dotted wave pattern.","src":"/images/work/2k-shopping/hero.webp","width":1920,"height":1200},{"alt":"2K Shopping billboard mockup reading \"Everyday things matter,\" with the wordmark, a QR code and app-store badges over a dark teal background.","src":"/images/work/2k-shopping/gallery-1.webp","width":1920,"height":1080},{"alt":"2K Shopping insulated delivery bags and backpack in neon lime green, with the logo and bilingual tagline.","src":"/images/work/2k-shopping/gallery-2.webp","width":1920,"height":1080},{"alt":"2K Shopping brand guideline color palette: black, dark teal, off-white, white, lime green and teal swatches with a reserved orange highlight color, RGB and CMYK values.","src":"/images/work/2k-shopping/gallery-3.webp","width":1920,"height":1080}]', '{"title":"2K Shopping: Branding & Visual Identity | Propagenda","description":"Case study: full bilingual (English/Arabic) brand identity and application system for a UAE-based online grocery delivery platform."}', '2K Shopping', 'Online Grocery Delivery', NULL, '/images/work/2k-shopping/hero.webp', '["Full logo system: construction, concept, vertical, horizontal and simplified-mark variations","Brand strategy: positioning, value proposition, core values, personality and tone-of-voice guidelines","Bilingual (English/Arabic) typography system and color palette","Icon style, pattern and imagery guidelines","Delivery van livery, delivery bags/backpack and shipping box with branded tape","Billboard and social media style guide","Stationery and staff collateral: business cards, letterhead, presentation folder, staff ID badge, uniforms and notebook"]', NULL, 'A UAE grocery delivery app entering a crowded, low-differentiation category, with no visual system to carry it from the app icon to the delivery van.', 'A bilingual system built on a lime-and-teal palette and a shopping-cart-and-K mark, carried through the app, packaging, fleet and every application.', 'One consistent identity now runs from the app splash screen to the delivery van and every piece of stationery.', NULL, NULL, 'arabian-business-academy', 'alla-doresu', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('alla-doresu', 'en', 'published', 10, 'Alla Doresu: Branding & Visual Identity', 'ALLA DORESU: BRANDING & VISUAL IDENTITY', 'more', 'Fashion & apparel', 'A Dubai fashion label built around a pink-and-black identity and its founder''s eye for detail. We carried it from hang tag to storefront.', '["Logo design and brand identity: monogram mark, wordmark and lockup construction","Brand colors, typography and a repeating monogram pattern","Packaging: branded paper bags in two colorways and a wax seal stamp","Retail merchandise: branded phone cases","Stationery: business cards, letterhead and envelopes","Staff ID badge and lanyard design","Product hang tags"]', '[{"alt":"Alla Doresu business card mockup in black with the pink monogram and repeating logo pattern, beside a pink branding-guidelines book.","src":"/images/work/alla-doresu/hero.webp","width":1920,"height":1080},{"alt":"Alla Doresu branded paper bags in pink and black, with the monogram mark and \"Unique as you are\" tagline.","src":"/images/work/alla-doresu/gallery-1.webp","width":1920,"height":1080},{"alt":"Alla Doresu branded phone cases in black and pink, each with the interlocking monogram mark and wordmark.","src":"/images/work/alla-doresu/gallery-2.webp","width":960,"height":1080},{"alt":"Alla Doresu letterhead stationery mockup with the pink-and-black logo lockup and Dubai, UAE contact details.","src":"/images/work/alla-doresu/gallery-3.webp","width":1920,"height":1080}]', '{"title":"Alla Doresu: Branding & Visual Identity | Propagenda","description":"Case study: full brand identity and application system for a Dubai women''s fashion label founded by designer Alaa Aldeeb."}', 'Alla Doresu', 'Fashion & Apparel', NULL, '/images/work/alla-doresu/hero.webp', '["Logo system: monogram mark, wordmark and lockup construction guidelines","Brand colors, typography and repeating monogram pattern","Packaging: paper bags in two colorways and a wax seal stamp","Branded phone cases","Stationery: business cards, letterhead and envelopes","Staff ID badge and lanyard","Product hang tags"]', NULL, 'A new Dubai fashion label needed one identity that could travel from a product hang tag to a shopping bag to the founder''s own business card.', 'A pink-and-black system built on an interlocking U-and-N monogram, carried through packaging, stationery, staff ID and retail merchandise.', 'One consistent brand mark now runs across the label''s stationery, packaging and staff-facing collateral.', NULL, NULL, '2k-shopping', 'bil-events', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('bil-events', 'en', 'published', 11, 'BIL Events: Branding & Visual Identity', 'BIL EVENTS: BRANDING & VISUAL IDENTITY', 'more', 'Events', 'A Dubai company built at the intersection of media and events. We gave it one identity built to run across a reality show, staff gear and a stationery suite.', '["Logo design and complete brand identity: primary \"BIL / EVENTS\" lockup and a secondary interlocking N monogram mark","Brand colors, typography and a repeating monogram pattern","Logo usage guidelines: construction, clear space, backgrounds and a secondary logo mark","Stationery: business cards, letterhead, envelopes and a presentation folder","Branded merchandise: caps, hoodies, T-shirts, silicone wristbands, phone cases and key chains","Staff ID badge and lanyard design","A wax-style rubber stamp","Roll-up banner design for the \"Spectacular Chaos\" reality-show campaign","Waiting-room / office signage application"]', '[{"alt":"BIL Events grey-and-yellow \"BIL / EVENTS\" wordmark applied as wall signage in a waiting area with yellow armchairs.","src":"/images/work/bil-events/hero.webp","width":1920,"height":1080},{"alt":"BIL Events roll-up banner mockup for the \"Spectacular Chaos\" reality-show campaign, listing the @bileventdxb social handle and bilevents.dxb website.","src":"/images/work/bil-events/gallery-1.webp","width":1920,"height":1080},{"alt":"BIL Events business card mockup for founder Layal Al Mais, in white with a yellow color-block and the interlocking N monogram.","src":"/images/work/bil-events/gallery-2.webp","width":1920,"height":1080},{"alt":"BIL Events staff ID badge and lanyard in yellow, grey and white with a repeating interlocking N monogram pattern.","src":"/images/work/bil-events/gallery-3.webp","width":960,"height":1080},{"alt":"BIL Events branded T-shirts in white with a yellow interlocking N monogram on the front and the \"BIL / EVENTS\" wordmark on the back.","src":"/images/work/bil-events/gallery-4.webp","width":1920,"height":1080}]', '{"title":"BIL Events: Branding & Visual Identity | Propagenda","description":"Case study: full brand identity and merchandise system for a Dubai media-and-events company launching a reality show and a super app."}', 'BIL Events', 'Media & Events', NULL, '/images/work/bil-events/hero.webp', '["Logo system: primary lockup and secondary interlocking N monogram","Brand colors, typography and repeating monogram pattern","Logo usage guidelines: construction, clear space, backgrounds and secondary mark","Stationery: business cards, letterhead, envelopes and presentation folder","Branded merchandise: caps, hoodies, T-shirts, wristbands, phone cases and key chains","Staff ID badge and lanyard","Rubber stamp","Roll-up banner for the \"Spectacular Chaos\" campaign","Waiting-room signage application"]', NULL, 'A new media-and-events company, founded on a background in event planning, PR and media, needed one identity that could carry a reality-show campaign, staff merchandise and a full stationery suite at once.', 'A grey-and-yellow system built on a stacked "BIL / EVENTS" wordmark and an interlocking N monogram, carried across stationery, staff gear, retail merchandise and campaign signage.', 'One consistent brand mark now runs from the founder''s business card to staff lanyards, merchandise and the roll-up banners for the company''s reality-show campaign.', NULL, NULL, 'alla-doresu', 'chicky-fighter', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('chicky-fighter', 'en', 'published', 12, 'Chicky Fighter: Packaging & Brand Identity', 'CHICKY FIGHTER: PACKAGING & BRAND IDENTITY', 'more', 'Food & hospitality', 'A Dubai fast-food menu of burgers, chicken and pizza. We gave it one fighting mascot and a packaging system to carry it.', '["Logo design and brand mascot: a red script \"Chicky\" wordmark over a bold \"FIGHTER\" lockup, with a boxing-themed fighting-chick character","Comic-book visual language: bold outline linework, halftone dot textures and speech-burst callouts (\"BURGERS!\", \"CHICKYS!\", \"PIZZA!\")","Packaging design across the full menu: burger box, chicken-tender boxes, pizza box, sandwich pack, fries pouch and a drink bottle label","Takeaway paper bag design","Menu naming and tagline copywriting (\"Luv Dat Burger,\" \"Luv Dat Chicken,\" \"Let the Battle Begin!\")"]', '[{"alt":"Chicky Fighter burger box with a red-and-yellow \"Luv Dat Burger\" logo lockup and the boxing-themed fighting-chick mascot.","src":"/images/work/chicky-fighter/hero.webp","width":1600,"height":2000},{"alt":"Chicky Fighter burger box wrapped in a repeating burger-outline pattern, with the \"Luuv Dat Burger\" wordmark and mascot.","src":"/images/work/chicky-fighter/gallery-1.webp","width":1920,"height":2400},{"alt":"Chicky Fighter chicken-tender boxes in red and yellow colorways, with a \"Chickys!\" comic burst, the mascot and a fried-chicken-bucket illustration.","src":"/images/work/chicky-fighter/gallery-2.webp","width":2000,"height":1500},{"alt":"Chicky Fighter kraft pizza boxes, open and closed, with a \"Pizza!\" comic burst and the fighting-chick mascot on a halftone-dot background.","src":"/images/work/chicky-fighter/gallery-3.webp","width":2000,"height":1500},{"alt":"Chicky Fighter chicken box printed with boxing-ring ropes and the \"Let the Battle Begin!\" tagline alongside \"Luv Dat Chicken.\"","src":"/images/work/chicky-fighter/gallery-4.webp","width":1600,"height":1067}]', '{"title":"Chicky Fighter: Packaging & Brand Identity | Propagenda","description":"Case study: comic-book brand identity and a full packaging system for a Dubai fast-food chicken and burger restaurant."}', 'Chicky Fighter', 'Fast-Food Restaurant', NULL, '/images/work/chicky-fighter/hero.webp', '["Logo and brand mascot system: wordmark plus fighting-chick character","Packaging: burger box, two chicken-tender box designs, kraft pizza box, sandwich pillow pack, fries pouch and drink bottle label","Takeaway paper bag","Comic-style tone of voice and menu-item naming"]', NULL, 'A fast-food menu spanning burgers, chicken, pizza and sides, with every box, bag and pouch needing to read as one brand.', 'A red-and-yellow comic-book system built around a fighting-chick mascot, carried across every box, bag, pouch and bottle in the menu.', 'From the burger box to the fries pouch, every package now carries the same mascot, palette and battle-themed voice.', NULL, NULL, 'bil-events', 'al-rowad-international', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('al-rowad-international', 'en', 'published', 13, 'Al Rowad International Intellectual Property: Branding & Visual Identity', 'AL ROWAD INTERNATIONAL INTELLECTUAL PROPERTY: BRANDING & VISUAL IDENTITY', 'more', 'Legal & professional services', 'A Dubai intellectual-property firm working across borders. We gave it one bilingual identity, from the official stamp to the email footer.', '["Logo design and complete brand identity: a three-bar \"R\" monogram in navy and orange, wordmark and \"International Intellectual Property\" tagline lockup","Brand colors and typography system in navy blue and orange","Stationery: letterhead, envelope and email signature","A bilingual (Arabic/English) rubber stamp for official documents","Invoice and quotation templates","Branded merchandise: pen and phone case","Staff ID badge and lanyard design"]', '[{"alt":"Al Rowad International Intellectual Property rubber stamp and its bilingual Arabic/English impression, reading \"Al Rowad International Intellectual Property\" around the R monogram.","src":"/images/work/al-rowad-international/hero.webp","width":1778,"height":2000},{"alt":"Al Rowad International Intellectual Property letterhead mockup with the navy-and-orange logo lockup and Dubai, UAE contact details.","src":"/images/work/al-rowad-international/gallery-1.webp","width":1920,"height":1080},{"alt":"Al Rowad International Intellectual Property invoice and quotation templates in navy and orange, with service and price tables.","src":"/images/work/al-rowad-international/gallery-2.webp","width":1920,"height":1080},{"alt":"Al Rowad International Intellectual Property staff ID badge and lanyard in white and navy with a repeating monogram pattern.","src":"/images/work/al-rowad-international/gallery-3.webp","width":2666,"height":3000},{"alt":"Al Rowad International Intellectual Property branded phone cases in an orange-to-navy gradient with a repeating monogram pattern.","src":"/images/work/al-rowad-international/gallery-4.webp","width":1920,"height":1080}]', '{"title":"Al Rowad International Intellectual Property: Branding & Visual Identity | Propagenda","description":"Case study: full bilingual (Arabic/English) brand identity and stationery system for a Dubai intellectual-property registration and protection firm."}', 'Al Rowad International Intellectual Property', 'Intellectual Property Services', NULL, '/images/work/al-rowad-international/hero.webp', '["Logo and complete brand identity: three-bar \"R\" monogram, wordmark and tagline lockup","Brand colors and typography system","Stationery: letterhead, envelope and email signature","Bilingual (Arabic/English) rubber stamp","Invoice and quotation templates","Branded merchandise: pen and phone case","Staff ID badge and lanyard"]', NULL, 'A Dubai IP registration and protection firm needed one identity that could carry from a legal rubber stamp to a letterhead to an email footer, in both Arabic and English.', 'A navy-and-orange system built on a three-bar "R" monogram, carried across stationery, the official bilingual stamp, and staff and branded merchandise.', 'One consistent mark now runs from the company stamp to the letterhead, the email signature and staff ID badges.', NULL, NULL, 'chicky-fighter', 'cu-optics', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('cu-optics', 'en', 'published', 14, 'C U Optics: Branding & Visual Identity', 'C U OPTICS: BRANDING & VISUAL IDENTITY', 'more', 'Healthcare & retail', 'A Dubai eyewear retailer selling glasses, sunglasses and colored contact lenses. We gave it one mark, a bilingual type system and a recurring Instagram campaign.', '["Logo design: an interlocking \"C\" and \"U\" mark drawn as a pair of glasses, with an \"OPTICS\" wordmark lockup","Logo usage guidelines: color and background variations, clear-space grid","Brand colors and a repeating eyewear-icon pattern (aviator, round, cat-eye and rectangular frames)","Bilingual typography system: Red Hat Display (English) and Almarai (Arabic)","Stationery: business card, letterhead and DL/A5 envelopes","Social media campaign system: Instagram grid and story templates for product, model and colored-contact-lens content"]', '[{"alt":"C U Optics Instagram grid campaign in an orange palette: sunglasses product shots, model close-ups and a \"Find your CHOICE\" post, with the interlocking C-and-U glasses mark.","src":"/images/work/cu-optics/hero.webp","width":1600,"height":1600},{"alt":"C U Optics Instagram grid campaign in a cyan palette: sunglasses product shots, colored-contact-lens close-ups and a \"Defend Your Vision\" post, with the interlocking C-and-U glasses mark.","src":"/images/work/cu-optics/gallery-1.webp","width":1600,"height":1600},{"alt":"C U Optics Instagram story in a cyan duotone, with a model in aviator-style sunglasses and the white interlocking C-and-U glasses logo lockup.","src":"/images/work/cu-optics/gallery-2.webp","width":1000,"height":1790},{"alt":"C U Optics Instagram story in a pink duotone reading \"Specialized in Eyewear,\" with a model wearing round sunglasses.","src":"/images/work/cu-optics/gallery-3.webp","width":1000,"height":1790},{"alt":"C U Optics Instagram story in an orange duotone reading \"Personalized Service,\" with a model wearing round glasses.","src":"/images/work/cu-optics/gallery-4.webp","width":1000,"height":1790},{"alt":"C U Optics Instagram story in a green duotone reading \"Wide Selection & Unique Styles,\" with a model wearing square-framed sunglasses.","src":"/images/work/cu-optics/gallery-5.webp","width":1000,"height":1790}]', '{"title":"C U Optics: Branding & Visual Identity | Propagenda","description":"Case study: full bilingual brand identity, stationery and Instagram campaign system for a Dubai eyewear retailer."}', 'C U Optics', 'Eyewear Retail', '2023', '/images/work/cu-optics/hero.webp', '["Logo system: primary mark, color/background variations and clear-space grid","Brand colors and repeating eyewear-icon pattern","Bilingual (English/Arabic) typography system: Red Hat Display and Almarai","Stationery: business card, letterhead and DL/A5 envelopes","Instagram grid campaign templates (product shots, model close-ups and colored-contact-lens callouts)","Instagram story templates for the brand’s \"about us\" series"]', NULL, 'A Dubai optical retailer, selling third-party eyewear and contact-lens brands, needed one identity to hold a brand guideline, a stationery suite and a running Instagram campaign together.', 'A cyan-and-orange system built on an interlocking C-and-U mark shaped like a pair of glasses, carried through bilingual stationery and a recurring Instagram grid-and-story campaign.', 'One mark and color system now runs from the business card to the Instagram grid and story campaigns.', NULL, NULL, 'al-rowad-international', 'al-manazel-al-haditha', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('al-manazel-al-haditha', 'en', 'published', 15, 'Al Manazel Al Haditha: Branding & Visual Identity', 'AL MANAZEL AL HADITHA: BRANDING & VISUAL IDENTITY', 'more', 'Property & interiors', 'A Dubai real estate brokerage in Business Bay. We built its identity from a wave-form monogram to a teal-and-gold stationery suite.', '["Logo design and complete brand identity: primary vertical lockup, secondary horizontal lockup and a simplified logo mark","Brand colors, typography and a repeating wave-form pattern built from the logo mark","Logo usage guidelines: clear space, backgrounds and misuse examples","Stationery: business cards, letterhead, envelopes and a presentation folder","Branded pens and other small collateral","Full brand guidelines document: brand story, values and target audience"]', '[{"alt":"Al Manazel Al Haditha Real Estate business card and envelope mockup in deep teal with a gold wave-form monogram, on marble.","src":"/images/work/al-manazel-al-haditha/hero.webp","width":1920,"height":1080},{"alt":"Al Manazel Al Haditha Real Estate logo lockup variations: the vertical primary logo and the horizontal secondary logo, in gold on teal.","src":"/images/work/al-manazel-al-haditha/gallery-1.webp","width":1920,"height":1080},{"alt":"Al Manazel Al Haditha Real Estate letterhead mockup with the logo lockup and a bilingual English/Arabic contact footer.","src":"/images/work/al-manazel-al-haditha/gallery-2.webp","width":1920,"height":1080},{"alt":"Al Manazel Al Haditha Real Estate brand color palette: white, gold, deep teal, near-black teal and black swatches with hex codes.","src":"/images/work/al-manazel-al-haditha/gallery-3.webp","width":1920,"height":1080},{"alt":"Al Manazel Al Haditha Real Estate simplified logo mark, a gold wave-form monogram, shown bare and set on a solid teal card.","src":"/images/work/al-manazel-al-haditha/gallery-4.webp","width":1920,"height":1080}]', '{"title":"Al Manazel Al Haditha: Branding & Visual Identity | Propagenda","description":"Case study: full brand identity and guideline system for a Dubai real estate brokerage, from a wave-form monogram to a teal-and-gold stationery suite."}', 'Al Manazel Al Haditha Real Estate LLC', 'Real Estate Brokerage', NULL, '/images/work/al-manazel-al-haditha/hero.webp', '["Logo system: vertical, horizontal and simplified-mark lockups","Brand colors, typography and repeating wave-form pattern","Logo usage guidelines: clear space, background and misuse rules","Stationery: business cards, letterhead, envelopes and presentation folder","Branded pens","Brand guidelines document covering story, values and target audience"]', NULL, 'A new Dubai real estate brokerage, offering sales, leasing, investment advisory and property management, needed one documented identity to launch on.', 'A gold wave-form "M/H" monogram on deep teal, paired with a Cinzel display face and Abhaya Libre body text, carried through a full guidelines document and stationery suite under the line "Guiding You Home."', 'One documented brand system, from the vertical logo mark to the business card and letterhead, ready for the agency to launch and apply consistently.', NULL, NULL, 'cu-optics', 'ayoub-and-co', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('ayoub-and-co', 'en', 'published', 16, 'Ayoub & Co.: Branding & Company Profile Design', 'AYOUB & CO.: BRANDING & COMPANY PROFILE DESIGN', 'more', 'Property & interiors', 'A Dubai real estate agency founded by two engineer brothers in 2024. We gave it one identity, from the wordmark to the company profile clients see first.', '["Logo design and complete brand identity: an \"AYOUB & CO.\" wordmark with a \"Real Estate\" subline and a secondary ampersand monogram mark","Brand colors and typography system: black, white and maroon, paired with an Abhaya Libre display serif and Poppins for headlines and body copy","Logo usage guidelines: clear space, solid and photographic backgrounds, and logo-misuse rules","A repeating pattern built from the ampersand monogram","Company profile document design: about us, story, mission and vision, six service lines and a partners page"]', '[{"alt":"Ayoub & Co. Real Estate company profile cover and back-cover mockup, with the black ampersand-monogram logo, maroon architectural photography, the \"A Partnership You Can Trust\" tagline and Dubai contact details.","src":"/images/work/ayoub-and-co/hero.webp","width":1920,"height":1080},{"alt":"Ayoub & Co. Real Estate brand guideline page with a large white ampersand-and-\"CO.\" monogram and a maroon accent dot on black.","src":"/images/work/ayoub-and-co/gallery-1.webp","width":1920,"height":1080},{"alt":"Ayoub & Co. Real Estate mission and vision spread, black and maroon-duotone architectural photography with serif headline type.","src":"/images/work/ayoub-and-co/gallery-2.webp","width":1920,"height":1080},{"alt":"Ayoub & Co. Real Estate company profile spread on residential and commercial sales and leasing, maroon-duotone architectural photography.","src":"/images/work/ayoub-and-co/gallery-3.webp","width":1920,"height":1080},{"alt":"Ayoub & Co. Real Estate company profile spread on furnishing and styling services, maroon-duotone interior photography.","src":"/images/work/ayoub-and-co/gallery-4.webp","width":1920,"height":1080}]', '{"title":"Ayoub & Co.: Branding & Company Profile Design | Propagenda","description":"Case study: brand identity and company profile design for a Dubai real estate agency founded by two engineer brothers."}', 'Ayoub & Co.', 'Real Estate Agency', '2024', '/images/work/ayoub-and-co/hero.webp', '["Logo and complete brand identity: wordmark with \"Real Estate\" subline and secondary ampersand monogram","Brand colors and typography system: black, white and maroon with Abhaya Libre and Poppins","Logo usage guidelines: clear space, background and misuse rules","Repeating ampersand-monogram pattern","Company profile document: about, story, mission and vision, service lines and partners"]', NULL, 'A brand-new Dubai real estate agency, founded by two engineer brothers, needed one documented identity and company profile to launch on.', 'A black, white and maroon system built on an ampersand monogram, carried through the logo guidelines and a company profile document that lays out the founders’ story, six service lines and key partners.', 'One consistent identity now runs from the logo mark to the company profile clients see first.', NULL, NULL, 'al-manazel-al-haditha', 'shawarma-asaj', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('shawarma-asaj', 'en', 'published', 17, 'Shawerma A''saj: Packaging & Brand Identity', 'SHAWERMA A''SAJ: PACKAGING & BRAND IDENTITY', 'more', 'Food & hospitality', 'A Dubai shawarma and wraps restaurant. We gave it one packaging system to carry a menu of darahem boxes, platters, wraps and a takeaway bag.', '["Logo design and brand mark: a skewer-and-wrap icon built into the \"A''SAJ\" wordmark under a \"SHAWERMA\" header, in red-on-kraft and navy-on-red colorways","Two-color brand system in crimson red and navy blue, printed on kraft-brown and cream stock, with a repeating flame graphic and a line-art shawarma-wrap illustration","Packaging design across the full menu: a Darahem Box and Darahem Bliss box, a platters box, a wraps box, a pillow-style sandwich wrap pack, and a kraft takeaway paper bag","Gift-style Spicy/Regular variant boxes","QR-code integration on the wraps box, pillow pack and variant boxes for menu and ordering links","Menu naming and tagline copywriting across product lines (\"Made to Satisfy,\" \"Taste the Difference,\" \"Wrap It Up, Level It Up,\" \"The Best in Town\")"]', '[{"alt":"Shawerma A''saj Darahem Box, closed with the red-and-kraft skewer logo and open showing the \"Made to Satisfy\" tagline and Darahem Box menu list.","src":"/images/work/shawarma-asaj/hero.webp","width":1600,"height":1067},{"alt":"Shawerma A''saj kraft takeaway paper bag with a red line-art shawarma-wrap illustration behind the red-and-navy wordmark.","src":"/images/work/shawarma-asaj/gallery-1.webp","width":1600,"height":1067},{"alt":"Shawerma A''saj platters box, closed with a kraft-outlined \"A''SAJ\" pattern and open reading \"Taste the Difference\" with the platters menu list.","src":"/images/work/shawarma-asaj/gallery-2.webp","width":1600,"height":1067},{"alt":"Shawerma A''saj wraps box in red and kraft tones, reading \"Wrap It Up, Level It Up\" beside the full wraps menu list.","src":"/images/work/shawarma-asaj/gallery-3.webp","width":1600,"height":1051},{"alt":"Shawerma A''saj pillow-style sandwich wrap packs, a red pack with a line-art wrap illustration and menu list, and a navy pack with the skewer wordmark and Dubai, UAE contact QR panel.","src":"/images/work/shawarma-asaj/gallery-4.webp","width":1600,"height":1200},{"alt":"Shawerma A''saj gift-style Spicy and Regular variant boxes in navy and red, each with the skewer wordmark on the lid and a QR-code panel.","src":"/images/work/shawarma-asaj/gallery-5.webp","width":1600,"height":1600}]', '{"title":"Shawerma A''saj: Packaging & Brand Identity | Propagenda","description":"Case study: crimson-and-navy brand identity and a full packaging system for a Dubai shawarma and wraps restaurant."}', 'Shawerma A''saj', 'Fast-Food Restaurant', NULL, '/images/work/shawarma-asaj/hero.webp', '["Logo and brand mark: skewer-and-wrap icon built into the \"A''SAJ\" wordmark, in red and navy colorways","Two-color brand system (crimson red, navy blue) on kraft-brown and cream stock, with a flame motif and line-art shawarma illustration","Packaging: Darahem Box, Darahem Bliss box, platters box, wraps box, pillow-style sandwich wrap pack and kraft paper bag","Gift-style Spicy/Regular variant boxes with QR-code panels","Menu naming and tagline copy for each packaging line"]', NULL, 'A Dubai shawarma and wraps restaurant needed one packaging system to carry a menu spanning darahem boxes, platters, wraps and a takeaway bag, each with its own item list.', 'A crimson-and-navy system built around a skewer-and-wrap icon, carried across every box, bag and pillow-pack in the menu, each stamped with its own tagline and item list.', 'From the Darahem Box to the takeaway bag, every package now carries the same mark, palette and flame motif.', NULL, NULL, 'ayoub-and-co', 'dhc-luxury-real-estate', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('dhc-luxury-real-estate', 'en', 'published', 18, 'DHC Luxury Real Estate: Brand Identity & Company Profile', 'DHC LUXURY REAL ESTATE: BRAND IDENTITY & COMPANY PROFILE', 'more', 'Property & interiors', 'A luxury real estate brokerage on Palm Jumeirah. We gave it a wordmark, a navy-and-gold palette and the bilingual company profile it hands to investors.', '["Logo design: an interlocking \"DHC\" monogram paired with a \"Luxury Real Estate\" wordmark","Brand colors and typography: navy blue and gold on a warm beige ground","Bilingual (Arabic/English) company profile document design, \"الملف التعريفي\"","Content structure: who we are, vision, values, services, experience, target sectors, team, partners, competitive advantages"]', '[{"alt":"DHC Luxury Real Estate company profile cover mockup, navy monogram logo and gold \"Company Profile\" Arabic and English lockup on a beige brochure.","src":"/images/work/dhc-luxury-real-estate/hero.webp","width":1920,"height":1080},{"alt":"DHC Luxury Real Estate values spread with a gold \"V\" award icon over a 3D building render, navy Arabic value labels.","src":"/images/work/dhc-luxury-real-estate/gallery-1.webp","width":1920,"height":1080},{"alt":"DHC Luxury Real Estate partners and team spread listing Emaar, Sobha Realty, Binghatti, Aldar, Nakheel and Meraas, with three team headshots.","src":"/images/work/dhc-luxury-real-estate/gallery-2.webp","width":1920,"height":1080},{"alt":"DHC Luxury Real Estate competitive advantages spread listing Golden Visa and financial services, with a UAE Golden Visa card mockup.","src":"/images/work/dhc-luxury-real-estate/gallery-3.webp","width":1920,"height":1080},{"alt":"DHC Luxury Real Estate closing page with the Arabic tagline \"For luxury, for quality, for trust\" beside the navy DHC monogram logo.","src":"/images/work/dhc-luxury-real-estate/gallery-4.webp","width":1920,"height":1080}]', '{"title":"DHC Luxury Real Estate: Brand Identity & Company Profile | Propagenda","description":"Case study: brand identity and Arabic/English company profile design for a Palm Jumeirah luxury real estate brokerage."}', 'DHC Luxury Real Estate', 'Real Estate Brokerage', NULL, '/images/work/dhc-luxury-real-estate/hero.webp', '["Logo and interlocking \"DHC\" monogram with \"Luxury Real Estate\" wordmark","Navy-and-gold brand palette on a warm beige ground","Bilingual (Arabic/English) company profile document"]', NULL, 'A Palm Jumeirah luxury real estate brokerage needed one documented identity and an investor-facing company profile written in Arabic and English.', 'A navy-and-gold system built around an interlocking "DHC" monogram, carried through a bilingual company profile that lays out the vision, six service lines, the team and named developer partners.', 'One navy-and-gold identity now runs from the logo mark to the bilingual company profile clients see first.', NULL, NULL, 'shawarma-asaj', 'laya-inc', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('laya-inc', 'en', 'published', 19, 'Laya Inc: Corporate Identity & Stationery System', 'LAYA INC: CORPORATE IDENTITY & STATIONERY SYSTEM', 'more', 'Professional services', 'A UAE professional services company. We gave it one documented identity, from the logo clear-space rules to the stationery and staff uniform.', '["Logo design and complete brand identity: an interlocking chevron \"A\" and \"V\" mark paired with a \"LAYA INC\" wordmark, in a vertical and a horizontal lockup","Brand colors and typography system: gold (#B08D68), beige (#E9DCCF) and cream (#FCF5EF) on black, set in Lato","Logo usage guidelines: construction, clear space, solid and photographic backgrounds, and logo-misuse rules","A repeating chevron pattern built from the logo mark","Stationery: business card, letterhead, envelope and a presentation folder","Branded merchandise: desk flags, a notebook and a polo shirt"]', '[{"alt":"Laya Inc logo mark and wordmark in gold on a warm beige textured wall, showing the interlocking chevron \"A\" and \"V\" mark above the LAYA INC lockup.","src":"/images/work/laya-inc/hero.webp","width":1920,"height":1080},{"alt":"Laya Inc business card mockup, gold logo mark on a cream front and the back card for Layal Al Mais with a repeating chevron pattern.","src":"/images/work/laya-inc/gallery-1.webp","width":1920,"height":1080},{"alt":"Laya Inc letterhead mockup with the gold logo lockup, a repeating chevron watermark and UAE contact details in the footer.","src":"/images/work/laya-inc/gallery-2.webp","width":1920,"height":1080},{"alt":"Laya Inc presentation folder mockup in gold and cream, with the logo lockup on the front flap and a \"Get in Touch\" contact panel on the back cover.","src":"/images/work/laya-inc/gallery-3.webp","width":1920,"height":1080},{"alt":"Laya Inc desk flags in gold and cream, one showing the repeating chevron pattern and the other the full LAYA INC logo lockup.","src":"/images/work/laya-inc/gallery-4.webp","width":1920,"height":1080},{"alt":"Laya Inc black polo shirt mockup with a gold chevron-pattern band on the front and the logo lockup and contact details printed on the back.","src":"/images/work/laya-inc/gallery-5.webp","width":1920,"height":1080}]', '{"title":"Laya Inc: Corporate Identity & Stationery System | Propagenda","description":"Case study: gold-and-black corporate identity and stationery system for a UAE professional services company, from logo guidelines to staff uniform."}', 'Laya Inc', 'Professional Services', '2024', '/images/work/laya-inc/hero.webp', '["Logo and complete brand identity: interlocking chevron mark with vertical and horizontal wordmark lockups","Brand colors and typography system: gold, beige and cream on black, set in Lato","Logo usage guidelines: construction, clear space, background and misuse rules","Repeating chevron-pattern graphic","Stationery: business card, letterhead, envelope and presentation folder","Branded merchandise: desk flags, notebook and polo shirt"]', NULL, 'A UAE professional services company needed one documented identity system, from the logo’s clear-space rules to a full stationery and merchandise suite.', 'A gold, beige and black system built on an interlocking chevron mark, carried across the guidelines, stationery, desk flags and staff polo shirt.', 'One consistent identity now runs from the logo usage guidelines to the business card, letterhead and staff uniform.', NULL, NULL, 'dhc-luxury-real-estate', 'vid', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('vid', 'en', 'published', 20, 'VID: Branding & Visual Identity', 'VID: BRANDING & VISUAL IDENTITY', 'more', 'Property & interiors', 'An interior design firm shaping homes, offices and commercial spaces. We gave it one documented identity, from the logo clear-space rules to the catalog and Instagram templates.', '["Full brand guidelines document: mission statement and three core values (Creativity, Functionality, Sustainability)","Logo design: a hand-sketched serif \"VID\" wordmark paired with a fragmented triangle mark, plus the line \"We think a little different\"","Logo usage guidelines: clear-space measurements and color/background variations across navy, copper, black and light-gray","Brand colors: Navy (#354151) and Copper (#8A674B), plus black and light gray","A repeating fragmented-triangle pattern system","Typography system built on a single display serif, AustinCyr Roman","Stationery: business card, letterhead and envelopes","Catalog booklet design and a sketch-presentation format","Social media template set: Instagram post and story layouts for project features"]', '[{"alt":"VID interior design brand identity: navy and white business card mockup with the hand-sketched \"VID\" wordmark and \"We think a little different\" tagline.","src":"/images/work/vid/hero.webp","width":1920,"height":1080},{"alt":"VID brand color palette: Navy #354151 and Copper #8A674B swatches with CMYK values, alongside the logo shown on navy, copper, black and light-gray backgrounds.","src":"/images/work/vid/gallery-1.webp","width":1920,"height":1080},{"alt":"VID catalog booklet mockup, open to interior renders of a reception and lounge space beside a black cover reading \"VID CATALOG.\"","src":"/images/work/vid/gallery-2.webp","width":1920,"height":1080},{"alt":"VID letterhead mockup with the sketched wordmark, a fragmented triangle pattern band and a copper triangle mark in the footer.","src":"/images/work/vid/gallery-3.webp","width":1920,"height":1080},{"alt":"VID Instagram templates: a \"5 Simple Ways to Create the Illusion of Space\" story and a living-room post captioned \"Functional Aesthetics for Every Setting.\"","src":"/images/work/vid/gallery-4.webp","width":1920,"height":1080}]', '{"title":"VID: Branding & Visual Identity | Propagenda","description":"Case study: full brand identity and guideline system for an interior design firm, from a hand-sketched wordmark to a catalog and Instagram template suite."}', 'VID', 'Interior Design', NULL, '/images/work/vid/hero.webp', '["Brand guidelines document: mission statement and core values","Logo and wordmark system: hand-sketched \"VID\" mark, fragmented triangle icon and tagline lockup","Logo usage guidelines: clear space and color/background variations","Brand colors: Navy and Copper, plus black and light-gray neutrals","Repeating fragmented-triangle pattern","Typography system: AustinCyr Roman","Stationery: business card, letterhead and envelopes","Catalog booklet and sketch-presentation layout","Instagram post and story templates"]', NULL, 'An interior design firm working across homes, offices and commercial spaces, with no documented visual system to carry that range of work.', 'A hand-sketched serif wordmark and a fragmented navy-and-copper triangle mark, carried through a full guidelines document, stationery suite, catalog and Instagram templates under the line "We think a little different."', 'One documented system now runs from the logo clear-space rules to the business card, catalog and Instagram templates.', NULL, NULL, 'laya-inc', 'alateeq-cafe', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('alateeq-cafe', 'en', 'published', 21, 'Alateeq Cafe: Branding & Visual Identity', 'ALATEEQ CAFE: BRANDING & VISUAL IDENTITY', 'more', 'Food & hospitality', 'A UAE cafe named for its Arabic calligraphic mark. We gave it one documented identity, from the logo clear-space grid to the coffee cup on the table.', '["Logo design: a gold Arabic calligraphic wordmark (العتيق) paired with an \"Alateeq cafe\" English script lockup","Logo usage guidelines: clear-space and construction grid, color and background variations across black, white, tan and teal","Brand colors: white, pale cream-green, tan/gold, teal and black","A repeating geometric pattern built from the logo’s curved letterforms","Typography system: Poppins for Latin type, paired with a bold Arabic display face","Stationery: business card and envelope","Tableware and table settings: napkin ring, branded plate, patterned placemat and an embossed coffee cup"]', '[{"alt":"Alateeq Cafe gold-foil calligraphic wordmark embossed on a blue paper stock, branding guidelines cover.","src":"/images/work/alateeq-cafe/hero.webp","width":1920,"height":1080},{"alt":"Alateeq Cafe logo lockup shown in white on black and in gold-and-teal on white, with the \"Alateeq cafe\" script wordmark beneath each mark.","src":"/images/work/alateeq-cafe/gallery-1.webp","width":1920,"height":1080},{"alt":"Alateeq Cafe brand color palette: white, pale cream-green, tan/gold, teal and black swatches, beside the repeating geometric pattern built from the logo letterforms.","src":"/images/work/alateeq-cafe/gallery-2.webp","width":1920,"height":1080},{"alt":"Alateeq Cafe business card and envelope mockup with the gold calligraphic wordmark and a patterned edge band.","src":"/images/work/alateeq-cafe/gallery-3.webp","width":1920,"height":1080},{"alt":"Alateeq Cafe branded placemat in a tan, teal and black geometric pattern, set with cutlery and drinks on a wooden table.","src":"/images/work/alateeq-cafe/gallery-4.webp","width":1920,"height":1080},{"alt":"Alateeq Cafe cork napkin ring stamped with the calligraphic mark, beside a branded plate in the geometric pattern.","src":"/images/work/alateeq-cafe/gallery-5.webp","width":1920,"height":1080},{"alt":"Alateeq Cafe coffee cup embossed with the calligraphic wordmark, set on a table with a matching saucer.","src":"/images/work/alateeq-cafe/gallery-6.webp","width":1920,"height":1080}]', '{"title":"Alateeq Cafe: Branding & Visual Identity | Propagenda","description":"Case study: bilingual Arabic-calligraphy brand identity and a print-to-tableware guideline system for a UAE cafe."}', 'Alateeq Cafe', 'Cafe', NULL, '/images/work/alateeq-cafe/hero.webp', '["Logo and calligraphic wordmark system: Arabic mark with English script lockup","Logo usage guidelines: clear-space and construction grid, color and background variations","Brand colors: white, pale cream-green, tan/gold, teal and black","Repeating geometric pattern built from the logo letterforms","Bilingual typography system: Poppins and a bold Arabic display face","Stationery: business card and envelope","Tableware: napkin ring, branded plate, placemat and embossed coffee cup"]', NULL, 'A cafe built around a hand-drawn Arabic calligraphic name, needing one mark that could carry from a coffee cup to a business card.', 'A gold-and-teal calligraphic wordmark paired with a Latin script lockup, carried through a repeating geometric pattern built from the letterforms across stationery and tableware.', 'One documented system now runs from the embossed coffee cup to the envelope flap and staff business card.', NULL, NULL, 'vid', 'jordanian-social-club', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('jordanian-social-club', 'en', 'published', 22, 'Jordanian Social Club: Brand Identity Guidelines', 'JORDANIAN SOCIAL CLUB: BRAND IDENTITY GUIDELINES', 'more', 'Community & culture', 'The cultural hub for Jordanians in the UAE. We documented one identity, from its story and values to a logo, color and type system.', '["Full brand identity guidelines document: foundation (story, core values, target audience), visual identity (logo system, colors, typography) and brand assets (elements, iconography, patterns)","Logo system: a crown-and-shield mark carrying the Jordanian flag''s seven-pointed star and green, red and black colors, topped by the Hashemite royal crown, in a vertical (primary) and horizontal (secondary) lockup","An independent crown-only brand mark for limited space, social media profile pictures and website favicon use","Bilingual (Arabic/English) wordmark and logo usage guidelines: clear space, background and misuse rules","Brand color palette: National Black, National White, National Green, National Red and Crown Grey, with hex codes","Bilingual typography system: Tharwat Emara Ruqaa and Gulf Light for Arabic, Bebas Neue and Novecento Sans Wide for English","A social media icon system carrying the national colors","Repeating horizontal and vertical geometric pattern built from the shield''s flag motif"]', '[{"alt":"Jordanian Social Club crown-and-shield logo embossed on a dark green textured cover, with the Arabic and English \"Jordanian Social Club\" wordmark.","src":"/images/work/jordanian-social-club/hero.webp","width":1920,"height":1080},{"alt":"Jordanian Social Club official logo lockups: vertical (primary) and horizontal (secondary) versions of the crown-and-shield mark with the bilingual wordmark.","src":"/images/work/jordanian-social-club/gallery-1.webp","width":1920,"height":1080},{"alt":"Jordanian Social Club logo shown on light and dark background usage, in full color and in reversed white.","src":"/images/work/jordanian-social-club/gallery-2.webp","width":1920,"height":1080},{"alt":"Jordanian Social Club brand color palette: National Black, National White, National Green, National Red and Crown Grey swatches with hex codes.","src":"/images/work/jordanian-social-club/gallery-3.webp","width":1920,"height":1080},{"alt":"Jordanian Social Club repeating horizontal geometric pattern built from the shield''s flag motif, in black on white.","src":"/images/work/jordanian-social-club/gallery-4.webp","width":1920,"height":1080}]', '{"title":"Jordanian Social Club: Brand Identity Guidelines | Propagenda","description":"Case study: full bilingual brand identity guidelines for the Jordanian Social Club, the cultural hub for Jordanians living in the UAE."}', 'Jordanian Social Club', 'Community & Cultural Organization', NULL, '/images/work/jordanian-social-club/hero.webp', '["Full brand identity guidelines document: foundation, visual identity and brand assets sections","Logo system: vertical (primary) and horizontal (secondary) lockups plus an independent crown brand mark","Bilingual (Arabic/English) wordmark and logo usage guidelines: clear space, background and misuse rules","Brand color palette: National Black, White, Green, Red and Crown Grey with hex codes","Bilingual typography system: Arabic (Tharwat Emara Ruqaa, Gulf Light) and English (Bebas Neue, Novecento Sans Wide)","Social media icon system in the national colors","Repeating horizontal and vertical geometric pattern"]', NULL, 'A Jordanian community club in Dubai needed one documented identity, from its foundation and values to a logo, color and type system, to represent Jordanians across the UAE.', 'A green-and-national-colors system built around a crown-and-shield mark carrying the Jordanian flag''s star and colors, documented across logo lockups, typography, color and a repeating geometric pattern.', 'One brand guidelines document now carries the club''s identity from its foundation and values through the logo system, color palette and social media icons.', NULL, NULL, 'alateeq-cafe', 'dot-and-dash', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('dot-and-dash', 'en', 'published', 23, 'Dot & Dash: Branding & Visual Identity', 'DOT & DASH: BRANDING & VISUAL IDENTITY', 'more', 'Professional services', 'A Dubai marketing agency named for two punctuation marks. We gave it one documented identity, from the ampersand mark’s clear-space grid to the business card and envelope.', '["Logo design: a black ampersand (\"&\") punctuated by a coral dash and dot, with stacked (vertical) and inline (horizontal) \"DOT & DASH\" wordmark lockups and a standalone simplified logo mark","Logo usage guidelines: clear-space measurements, solid-background chips (dark, coral, light gray) and photographic-background rules, plus a logo misuse reference sheet","Brand colors: Black, dark gray, coral (#FF3D57), light gray and white, each documented with hex and CMYK values and a set of brand associations","A repeating dot-and-dash pattern in coral, dark and light-gray tones","Typography system built on a single sans-serif family, Lato","Social media icon set: Facebook, Messenger, Instagram, WhatsApp, TikTok and YouTube, each in coral, dark and light-gray treatments","Stationery: business card, letterhead and envelope"]', '[{"alt":"Dot & Dash logo close-up: a black ampersand with a coral dash-and-dot accent, embossed on a white paper corner.","src":"/images/work/dot-and-dash/hero.webp","width":1920,"height":1080},{"alt":"Dot & Dash logo variations: stacked vertical lockup, inline horizontal lockup, and the standalone ampersand logo mark in a rounded-square chip.","src":"/images/work/dot-and-dash/gallery-1.webp","width":1920,"height":1080},{"alt":"Dot & Dash brand color palette: Black, dark gray, coral #FF3D57, light gray and white swatches with CMYK values and brand associations.","src":"/images/work/dot-and-dash/gallery-2.webp","width":1920,"height":1080},{"alt":"Dot & Dash business card mockup, front with the ampersand logo and back with a staff name and title.","src":"/images/work/dot-and-dash/gallery-3.webp","width":1920,"height":1080},{"alt":"Dot & Dash letterhead mockup with the logo lockup and a coral-and-black bar band above the letter body.","src":"/images/work/dot-and-dash/gallery-4.webp","width":1920,"height":1080}]', '{"title":"Dot & Dash: Branding & Visual Identity | Propagenda","description":"Case study: a full brand guideline system for a Dubai marketing agency, built around a black ampersand punctuated by a coral dot and dash."}', 'Dot & Dash', 'Marketing Agency', NULL, '/images/work/dot-and-dash/hero.webp', '["Logo and wordmark system: ampersand-and-dot mark, vertical and horizontal lockups, and a simplified logo mark","Logo usage guidelines: clear-space rules, background variations and a misuse reference sheet","Brand colors: Black, dark gray, coral, light gray and white with hex/CMYK values","Repeating dot-and-dash pattern","Typography system: Lato","Social media icon set across six platforms in three color treatments","Stationery: business card, letterhead and envelope"]', NULL, 'A marketing agency named for two punctuation marks, needing one mark that could carry that wordplay from a business card to a wall sign.', 'A black ampersand punctuated by a coral dash and dot, carried through clear-space and misuse guidelines, a repeating dot-and-dash pattern, and a Lato-based type system across stationery and social icons.', 'One documented system now runs from the ampersand mark’s clear-space grid to the business card and envelope.', NULL, NULL, 'jordanian-social-club', 'leoz', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('leoz', 'en', 'published', 24, 'Leoz Gents Salon: Branding & Visual Identity', 'LEOZ GENTS SALON: BRANDING & VISUAL IDENTITY', 'more', 'Beauty & grooming', 'A Dubai men’s grooming salon. We gave it one gold-and-black identity, from the lion mark’s clear-space grid to the storefront sign.', '["Logo design: a gold-gradient lion-head mark paired with a lowercase \"Leoz\" logotype and a serif \"GENTS SALON\" subtitle, in vertical (primary) and horizontal (secondary) lockups plus a standalone logo mark for small applications","Logo usage guidelines: clear-space measurement, solid- and photographic-background rules, and a logo misuse reference sheet","Brand colors: black, a bronze-to-gold gradient (#5a431c to #fcca6d) and a solid bronze-gold (#886703), each documented with hex and CMYK values","Typography system built on Poppins for headings and body copy","Icon set for Instagram, Facebook, phone, email and location, in gold-bracket and solid-black treatments","Social media ad templates for a grooming campaign (\"Think Again\")","Stationery and print collateral: business card, letterhead, feather banners, shopping bags and branded price-list stands","Staff uniform application: polo shirts and tunics"]', '[{"alt":"Leoz Gents Salon storefront signage at night: a script \"LeoZ Gents Salon\" sign and gold lion-head mark above the entrance, with \"Sharp Style, Strong Confidence\" overlaid.","src":"/images/work/leoz/hero.webp","width":1920,"height":1080},{"alt":"Leoz Gents Salon logo variations: vertical (primary) and horizontal (secondary) lockups of the gold lion-head mark and \"Leoz Gents Salon\" wordmark, plus a standalone logo mark in gold-on-white and gold-on-black.","src":"/images/work/leoz/gallery-1.webp","width":1920,"height":1080},{"alt":"Leoz Gents Salon brand color palette: black, a bronze-to-gold gradient (#5a431c to #fcca6d) and solid bronze-gold #886703 swatches with CMYK values.","src":"/images/work/leoz/gallery-2.webp","width":1920,"height":1080},{"alt":"Leoz Gents Salon business card and letterhead mockups showing the lion-head logo, Palm Jumeirah address and \"Precision in Every Cut\" tagline.","src":"/images/work/leoz/gallery-3.webp","width":1920,"height":1080},{"alt":"Leoz Gents Salon staff uniform application: a black polo shirt with the lion-head logo, and two staff tunics with the logo on the chest.","src":"/images/work/leoz/gallery-4.webp","width":1920,"height":1080}]', '{"title":"Leoz Gents Salon: Branding & Visual Identity | Propagenda","description":"Case study: a full brand identity guidelines system for Leoz Gents Salon, a Dubai men’s grooming salon, built around a gold-gradient lion-head mark."}', 'Leoz Gents Salon', 'Men’s Grooming & Barbershop', NULL, '/images/work/leoz/hero.webp', '["Logo and wordmark system: lion-head mark, vertical and horizontal lockups, and a standalone logo mark","Logo usage guidelines: clear-space rules, background variations and a misuse reference sheet","Brand colors: black, bronze-to-gold gradient and solid bronze-gold with hex/CMYK values","Typography system: Poppins","Icon set across five contact points in two color treatments","Social media campaign ad templates","Stationery and print collateral: business card, letterhead, banners, bags and price-list stands","Staff uniform application"]', NULL, 'A Dubai men’s grooming salon needing one gold-and-black identity that could carry from a business card to a storefront sign across two locations.', 'A gold-gradient lion-head mark paired with a lowercase "Leoz" logotype, carried through clear-space and misuse guidelines, a Poppins-based type system, and gold-bracket icons across stationery, uniforms and signage.', 'One documented system now runs from the lion mark’s clear-space grid to the Palm Jumeirah and DIFC storefronts.', NULL, NULL, 'dot-and-dash', 'lets-ad', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('lets-ad', 'en', 'published', 25, 'Let''s Ad Advertising: Brand Identity & Visual Guidelines', 'LET''S AD ADVERTISING: BRAND IDENTITY & VISUAL GUIDELINES', 'more', 'Advertising & Media', 'A Dubai out-of-home advertising company. We gave it a cyan-to-mint identity built to read from a billboard and hold up on a business card.', '["Logo design and brand identity: Primary, Secondary, Icon/Favicon/Socials and Logotype-only lockups","Logo construction, clear-space measurement and background-usage guidelines","Brand colors: a cyan-to-mint (#16b8e9 to #04fdd5) gradient system on black, white and light-gray (#e8e8e8) neutrals, documented with hex, RGB and CMYK values","Typography system built on Montserrat (Bold for headings, Medium and Light for body copy)","Icon set and a repeating brand pattern","Voice and tone guidelines, and a social media imagery style guide for an OOH/DOOH advertising brand","Applications: office stationery, marketing materials, and branded packaging and merchandise"]', '[{"alt":"Let''s Ad Advertising brand cover: a cyan-to-mint gradient logomark and \"LETS AD ADVERTISING\" wordmark embossed on a dark textured wall, with \"Visual Identity\" below.","src":"/images/work/lets-ad/hero.webp","width":1920,"height":1080},{"alt":"Let''s Ad Advertising logo variations: Primary and Secondary lockups of the cyan-to-mint gradient mark with the \"LETS AD ADVERTISING\" wordmark, plus a standalone Icon/Favicon/Socials mark and a Logotype-only lockup.","src":"/images/work/lets-ad/gallery-1.webp","width":1920,"height":1080},{"alt":"Let''s Ad Advertising brand color palette: black, white, light gray #e8e8e8, cyan #16b8e9 and mint #04fdd5 swatches with RGB and CMYK values.","src":"/images/work/lets-ad/gallery-2.webp","width":1920,"height":1080},{"alt":"Let''s Ad Advertising typography specimen: a display Heading 1 face over Montserrat Bold headings and Montserrat Medium/Light body copy.","src":"/images/work/lets-ad/gallery-3.webp","width":1920,"height":1080},{"alt":"Let''s Ad Advertising business card mockup in black, with the cyan-to-mint logo on the front and a repeating icon pattern along the edge.","src":"/images/work/lets-ad/gallery-4.webp","width":1920,"height":1080}]', '{"title":"Let''s Ad Advertising: Brand Identity & Visual Guidelines | Propagenda","description":"Case study: a full brand identity and visual guidelines system for Let''s Ad Advertising, a Dubai out-of-home (OOH/DOOH) advertising company, built around a cyan-to-mint gradient mark."}', 'Let''s Ad Advertising', 'Out-of-Home (OOH/DOOH) Advertising', NULL, '/images/work/lets-ad/hero.webp', '["Logo and lockup system: Primary, Secondary, Icon/Favicon/Socials and Logotype-only variations","Logo usage guidelines: clear-space measurement and background rules","Brand colors: cyan-to-mint gradient plus black, white and light-gray neutrals with hex/RGB/CMYK values","Typography system: Montserrat","Icon set and repeating brand pattern","Voice and tone guidelines, and a social imagery style guide","Stationery, marketing material and packaging/merchandise applications"]', NULL, 'A Dubai out-of-home advertising company needing one identity that could read as confidently on a billboard as it does on a business card.', 'A cyan-to-mint gradient mark and a Montserrat-based type system, documented across logo construction, color, typography, voice and social-imagery guidelines, and carried through stationery, marketing materials and packaging.', 'One documented system now runs from the logo''s clear-space grid to the business card and letterhead.', NULL, NULL, 'leoz', 'quick-cars', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('quick-cars', 'en', 'published', 26, 'Quick Cars: Branding & Visual Identity', 'QUICK CARS: BRANDING & VISUAL IDENTITY', 'more', 'Automotive', 'A Dubai pre-owned car dealership. We gave it a red, auburn and black identity built around a wing-shaped "QC" mark, from the logo’s clear-space grid to the branded key chain.', '["Logo design: a red wing-shaped mark combined with a \"Q&C\" monogram, in vertical (primary) and horizontal (secondary) lockups plus a standalone logo mark","Logo usage guidelines: construction grid, clear-space measurement, and solid- and photographic-background rules","Brand colors: White, Red (#FF0000), Auburn (#B21F2B), Grey (#515151) and Black, each documented with hex, CMYK and RGB values","Typography system built on Montserrat","A repeating chevron pattern and icon set","Stationery and print collateral: business card, letterhead, envelope, receipt, invoice/quotation, stamp, presentation folder","Merchandise and application design: flags, mugs, car key chains, car number plate holder and thermos, phone cases, cap, bomber jacket, T-shirt"]', '[{"alt":"Quick Cars brand cover: a white \"QUICK CARS\" wordmark and red wing-shaped \"QC\" logo mark over a red sports car with a matching white QC decal on the door, with \"Your Trusted Journey in Pre-Owned Cars\" below.","src":"/images/work/quick-cars/hero.webp","width":1920,"height":1080},{"alt":"Quick Cars logo variations: vertical and horizontal lockups of the red wing-shaped \"QC\" mark with the \"QUICK CARS\" wordmark, plus a standalone logo mark.","src":"/images/work/quick-cars/gallery-1.webp","width":1920,"height":1080},{"alt":"Quick Cars brand color palette: Auburn #B21F2B swatch with CMYK and RGB values, over a red car with a white QC side decal.","src":"/images/work/quick-cars/gallery-2.webp","width":1920,"height":1080},{"alt":"Quick Cars typography specimen: Montserrat uppercase and lowercase alphabet on black, beside a red chevron pattern.","src":"/images/work/quick-cars/gallery-3.webp","width":1920,"height":1080},{"alt":"Quick Cars branded car key chains in black and red with a repeating chevron pattern and gold hardware.","src":"/images/work/quick-cars/gallery-4.webp","width":1920,"height":1080}]', '{"title":"Quick Cars: Branding & Visual Identity | Propagenda","description":"Case study: a full brand identity guidelines system for Quick Cars, a Dubai pre-owned car dealership, built around a red wing-and-monogram logo mark."}', 'Quick Cars', 'Pre-Owned Car Dealership', NULL, '/images/work/quick-cars/hero.webp', '["Logo and lockup system: vertical (primary) and horizontal (secondary) lockups, plus a standalone logo mark","Logo usage guidelines: construction grid, clear-space rules and background variations","Brand colors: White, Red, Auburn and Grey neutrals plus Black, with hex/CMYK/RGB values","Typography system: Montserrat","Repeating chevron pattern and icon set","Stationery: business card, letterhead, envelope, receipt, invoice/quotation, stamp and presentation folder","Merchandise applications: flags, mugs, car key chains, car number plate holder and thermos, phone cases, cap, bomber jacket and T-shirt"]', NULL, 'A Dubai pre-owned car dealership needing one identity that could carry from a business card to a set of branded car key chains.', 'A red wing-shaped mark combined with a "Q&C" monogram, carried through construction and clear-space guidelines, a Montserrat-based type system, and a repeating chevron pattern across stationery and merchandise.', 'One documented system now runs from the logo’s clear-space grid to the key chain drivers take home.', NULL, NULL, 'lets-ad', 'serr-el-oud', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('serr-el-oud', 'en', 'published', 27, 'Serr El Oud: Brand Identity Guidelines', 'SERR EL OUD: BRAND IDENTITY GUIDELINES', 'more', 'Beauty & fragrance', 'A Tunisian oud perfume house. We gave it a bilingual identity in black, cream and a signature gold gradient, built around a monogrammed "S".', '["Full brand guidelines document: brand elements, concept, story, values and target audience","Logo design and construction: a circular \"S\" monogram combining the initial with a perfume-bottle silhouette, plus a stacked Arabic/English wordmark lockup","Logo usage guidelines: clear-space grid, minimum print/digital sizing, background rules and a \"please do not\" misuse page","Brand colors: a six-step gold gradient (Primary) and a cream neutral (Secondary), each documented with hex and CMYK values","Bilingual typography system: AustinCyr and Noto Serif for Latin type, Layla Pro for Arabic type","A repeating wave-line pattern and a companion paper texture","Icon style direction","Stationery: business card and letterhead"]', '[{"alt":"Serr El Oud gold-foil circular \"S\" monogram and stacked Arabic/English wordmark embossed on black leather beside white marble.","src":"/images/work/serr-el-oud/hero.webp","width":1920,"height":1080},{"alt":"Serr El Oud logo concept: the gold circular \"S\" monogram and Arabic/English wordmark embossed on white plaster under dappled leaf shadow.","src":"/images/work/serr-el-oud/gallery-1.webp","width":1920,"height":1080},{"alt":"Serr El Oud primary color palette: a six-step gold gradient from deep bronze to pale champagne, bookended by white and black, each with hex and CMYK values.","src":"/images/work/serr-el-oud/gallery-2.webp","width":1920,"height":1080},{"alt":"Serr El Oud repeating wave-line pattern in gold, shown on white paper and on a textured grey ground.","src":"/images/work/serr-el-oud/gallery-3.webp","width":1920,"height":1080},{"alt":"Serr El Oud business card mockup in matte black with gold foil founder details and the wave-line pattern embossed on the reverse.","src":"/images/work/serr-el-oud/gallery-4.webp","width":1920,"height":1080}]', '{"title":"Serr El Oud: Brand Identity Guidelines | Propagenda","description":"Case study: a bilingual (English/Arabic) brand identity system for Serr El Oud, a Tunisian oud perfume house, built around a monogram \"S\" mark in a signature gold gradient."}', 'Serr El Oud', 'Perfume', NULL, '/images/work/serr-el-oud/hero.webp', '["Full brand guidelines document","Logo and construction system: circular \"S\" monogram, clear-space grid and sizing rules","Logo misuse guidelines and background usage rules","Brand colors: gold gradient primary palette and cream secondary, with hex/CMYK values","Bilingual typography system: AustinCyr and Noto Serif (Latin), Layla Pro (Arabic)","Repeating wave-line pattern and paper texture","Icon style direction","Stationery: business card and letterhead"]', NULL, 'A Tunisian oud perfume house with a rich founding story and no documented visual system to carry it consistently across languages and materials.', 'A circular monogram fusing "S" and a perfume-bottle silhouette, rendered in a six-step gold gradient against black and cream, with a bilingual English/Arabic type system and a wave-line pattern echoing oud smoke.', 'One documented guidelines system now carries the Serr El Oud mark, in English and Arabic, from letterhead to business card.', NULL, NULL, 'quick-cars', 'sterling-cars', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('sterling-cars', 'en', 'published', 28, 'Sterling Cars: Brand Guidelines', 'STERLING CARS: BRAND GUIDELINES', 'more', 'Automotive', 'An Antwerp luxury car dealership. We gave it a blue, black, white and grey identity built around an infinity-and-handshake mark, under the tagline "Infinite Trade".', '["Full brand guidelines document: brand overview, target audience, core values, logo system, color palette, typography, icons, pattern, voice & tone, slogan structure and imagery style","Logo design and construction: an infinity-symbol mark with an integrated handshake, plus a \"Sterling Cars / Infinite Trade\" wordmark lockup","Logo usage guidelines: construction grid, clear-space rule (2x the icon-to-text gap) and background variations (black, blue, grey, white)","Logo variations: primary lockup, icon/favicon/socials mark, secondary lockup and logotype-only version","Brand colors: Primary blue, white and black, and a Secondary grey, each documented with hex, RGB and CMYK values","Typography system: Copperplate Gothic Std for headings (paired with Edwardian Script ITC for a decorative overlay), Nexa for body copy, and Cairo for Arabic type","Slogan structure guideline: a bold Copperplate Gothic Std line overlapping an Edwardian Script ITC line, centered with tight baseline alignment","Socials imagery style guide: cinematic, low-vibrancy car photography, with the brand blue used more vividly to highlight accents","Stationery, marketing materials, branded packaging & merchandise, and car accessories application mockups"]', '[{"alt":"Sterling Cars metallic infinity-and-handshake logo mark above the \"Sterling Cars / Infinite Trade\" wordmark on a smoky grey gradient background.","src":"/images/work/sterling-cars/hero.webp","width":1920,"height":1080},{"alt":"Sterling Cars brand guidelines cover: the \"Sterling Cars / Infinite Trade\" wordmark between two sports cars in a dark showroom.","src":"/images/work/sterling-cars/gallery-1.webp","width":1920,"height":1080},{"alt":"Sterling Cars logo variations: primary lockup, icon/favicon/socials mark, secondary lockup and logotype-only version of the infinity-and-handshake mark.","src":"/images/work/sterling-cars/gallery-2.webp","width":1920,"height":1080},{"alt":"Sterling Cars color palette: Primary blue, white and black swatches with hex/RGB/CMYK values, beside a Secondary grey gradient swatch.","src":"/images/work/sterling-cars/gallery-3.webp","width":1920,"height":1080},{"alt":"Sterling Cars slogan structure guideline: bold Copperplate Gothic Std headlines overlapping script Edwardian Script ITC taglines, e.g. \"Exquisite Cars / Infinite Trade\".","src":"/images/work/sterling-cars/gallery-4.webp","width":1920,"height":1080},{"alt":"Sterling Cars socials imagery style guide: cinematic, low-vibrancy luxury car photography with the brand blue used to highlight accents.","src":"/images/work/sterling-cars/gallery-5.webp","width":1920,"height":1080}]', '{"title":"Sterling Cars: Brand Guidelines | Propagenda","description":"Case study: a full brand identity guidelines system for Sterling Cars, an Antwerp, Belgium luxury car dealership, built around an infinity-and-handshake logo mark under the tagline \"Infinite Trade\"."}', 'Sterling Cars', 'Luxury Car Dealership', NULL, '/images/work/sterling-cars/hero.webp', '["Full brand guidelines document","Logo and construction system: infinity-and-handshake mark with clear-space grid and background rules","Logo variations: primary, icon/favicon/socials, secondary and logotype-only lockups","Brand colors: Primary blue, white and black, plus Secondary grey, with hex/RGB/CMYK values","Typography system: Copperplate Gothic Std and Edwardian Script ITC (headings), Nexa (body), Cairo (Arabic)","Slogan structure guideline and socials imagery style guide","Stationery, marketing materials, branded packaging & merchandise and car accessories application mockups"]', NULL, 'An Antwerp luxury dealership selling BMW, Ferrari, Mercedes-Benz, Rolls-Royce and Lamborghini needing one documented system to carry a premium, international tone across every touchpoint.', 'An infinity symbol fused with a handshake, paired with the "Infinite Trade" tagline, carried through a blue/black/white/grey palette and a Copperplate Gothic Std plus Edwardian Script ITC type pairing for headings.', 'One documented guidelines system now carries the Sterling Cars mark, from the logo’s clear-space grid to car accessories and merchandise.', NULL, NULL, 'serr-el-oud', 'mm-event-management', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
INSERT INTO case_studies (slug, locale, status, sort_order, title, h1, tier, category, overview, scope_items, gallery, seo, client, industry, year, hero_image, deliverables, results, challenge, approach, outcome, quote, accent, prev_slug, next_slug, published_at, created_at, updated_at) VALUES ('mm-event-management', 'en', 'published', 29, 'MM Event Management: Branding & Visual Identity', 'MM EVENT MANAGEMENT: BRANDING & VISUAL IDENTITY', 'more', 'Events', 'A Dubai event production company, legally Magic Music Event Management L.L.C. We gave it one documented identity, from the ribbon "M" mark to the festival banner.', '["Full brand guidelines document: brand story, values, target audience, logo system, colors, typography, pattern, icons and applications","Logo design and construction: a black circle badge holding a teal-to-white ribbon \"M\" mark, with vertical, horizontal and logo-mark lockups","Logo usage guidelines: clear-space rule (one-third the logo mark on all sides), solid and photographic-background variations, and a logo misuse reference sheet","Brand colors: black, teal (#00CECB) and off-white (#F3F4F4), each documented with hex and CMYK values and a set of brand associations","Typography system built on a single sans-serif family, Montserrat","A repeating chevron pattern built from the logo mark, in teal-on-black and outline-on-white variations","A circular icon set for contact points and social platforms (phone, email, web, location, Instagram, Facebook, X, YouTube, TikTok) in outline and filled treatments","Stationery: business card, letterhead and envelope, plus an email signature","A bilingual (English/Arabic) rubber stamp for \"Magic Music Event Management L.L.C.\"","Marketing and event applications: branded flags carrying the \"Spotlighting Good Times\" tagline, festival fence banners, a phone case and a staff ID badge and lanyard"]', '[{"alt":"MM Event Management branded flags on poles against a blue sky: a chevron-pattern flag, a white flag reading \"Spotlighting Good Times\" with the logo mark, and a teal chevron-pattern flag.","src":"/images/work/mm-event-management/hero.webp","width":1920,"height":1080},{"alt":"MM Event Management logo variations: vertical lockup, horizontal lockup and standalone logo mark, each a teal ribbon \"M\" in a black circle badge.","src":"/images/work/mm-event-management/gallery-1.webp","width":1920,"height":1080},{"alt":"MM Event Management brand color palette: black, teal #00cecb and off-white #F3F4F4 circles with CMYK values and brand associations.","src":"/images/work/mm-event-management/gallery-2.webp","width":1920,"height":1080},{"alt":"MM Event Management bilingual rubber stamp reading \"Magic Music Event Management L.L.C.\" in English and Arabic around the ribbon \"M\" mark.","src":"/images/work/mm-event-management/gallery-3.webp","width":1920,"height":1080},{"alt":"MM Event Management \"Open Air Festival\" fence banner in teal with the logo mark, set against a blurred festival stage.","src":"/images/work/mm-event-management/gallery-4.webp","width":1920,"height":1080}]', '{"title":"MM Event Management: Branding & Visual Identity | Propagenda","description":"Case study: a full brand guideline system for MM Event Management, a Dubai-based event production company trading as Magic Music Event Management L.L.C., built around a teal ribbon \"M\" mark under the tagline \"Spotlighting Good Times\"."}', 'MM Event Management', 'Event Production & Management', NULL, '/images/work/mm-event-management/hero.webp', '["Full brand guidelines document","Logo and construction system: ribbon \"M\" mark in a circle badge, with vertical, horizontal and logo-mark lockups","Logo usage guidelines: clear-space rule, background variations and a misuse reference sheet","Brand colors: black, teal and off-white, with hex/CMYK values","Typography system: Montserrat","Repeating chevron pattern built from the logo mark","Circular icon set across contact points and social platforms","Stationery: business card, letterhead, envelope and email signature","Bilingual (English/Arabic) rubber stamp","Flags, festival banners, phone case and staff ID badge and lanyard"]', NULL, 'A UAE event producer running weddings, festivals, corporate and educational events, needing one documented system to carry the same mark from a business card to a festival fence banner.', 'A teal ribbon "M" mark in a black circle badge, carried through a chevron pattern, a Montserrat-based type system, and a black/teal/off-white palette across stationery, a bilingual stamp, flags and event signage.', 'One documented guidelines system now carries the MM Event Management mark, from the logo’s clear-space rule to the festival banner and staff lanyard.', NULL, NULL, 'sterling-cars', 'emirates-agro', '2026-09-14T22:47:51.118+00:00', '2026-09-14T21:56:06.938008+00:00', '2026-09-14T22:47:51.828506+00:00');
